{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "Twilight overlook above shattered spires; an ink-stained coat sleeve pins a crinkled map down with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false invitations.",
      "visual_description": "A battered oil lamp on a stone ledge, single eye glowing in its flame, casting a long warning shadow toward distant castle gates.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the broken outer wall.",
      "visual_description": "A small clockwork fox with blue glass eyes creeping along crumbled battlements, key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips in through a cracked window.",
      "visual_description": "A figure in a clear diving helmet emerging from a tall pane as if from water, coat reflecting fractured city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team meets at a fountain of dry coins.",
      "visual_description": "A dusty plaza fountain choked with old coins; Mara, the lamp on its rim, and Tin Fox perched beside the diver's rippling reflection.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "They pass the tempting castle gates without stopping.",
      "visual_description": "Enormous iron gates yawning open with gilded banners; Mara walks past, eyes fixed on her compass, refusing the invitation.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "A cursed tower hums with stolen names.",
      "visual_description": "A leaning spire wrapped in chains of paper sigils; the oracle lamp's flame flickering nervously as it floats beside Glass Diver.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector blocking a doorway.",
      "visual_description": "A plump official slumped against a carved door, ledger as pillow, stamped papers stuck to his sleeves, snoring.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox steals the key from the dozing official's hand.",
      "visual_description": "Clockwork paws lifting a brass key from a limp pudgy hand, blue glass eyes glinting in lamplight.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a great winged beast drift through smoke.",
      "visual_description": "Painted scales on a tavern wall and shadow plumes overhead; Mara studying claw-scratched cobblestones with a frown.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver dives through a stained-glass royal portrait.",
      "visual_description": "A tall window depicting an old monarch shattering into ripples as the diver plunges through, coat trailing colored light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "An armored patrol clatters past in the alley below.",
      "visual_description": "From a high arch, Tin Fox and Mara crouching as plumed helmets and pikes march by in lantern-stripe shadows.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp reveals the hidden magic door.",
      "visual_description": "A blank stone wall where lamp-glow exposes silver glyphs forming an outline of a low arched door.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive curled inside a mirrored cell.",
      "visual_description": "A round room of facing mirrors; Glass Diver reaching a gloved hand toward a small reflected figure huddled in every pane.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector mumbles an alarm in his dreams.",
      "visual_description": "Down a far corridor, the official talks in his sleep as stamped papers flutter; bells beginning to twitch on their cords above him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox leads the dash through banner-hung halls.",
      "visual_description": "Tattered royal banners blurring overhead as the clockwork fox sprints ahead of running boots, sparks from its tail.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "They race onto the long bridge at dawn.",
      "visual_description": "A narrow stone bridge over a misted gorge; four silhouettes running east as the ruined city burns gold behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, Mara marks the map complete.",
      "visual_description": "A hillside camp at sunrise; the cartographer inks a small star on her map while the lamp glows softly and Tin Fox rests beside the diver.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    }
  ]
}

